package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public final class MetronomeActivity extends PocketActivity {
 private int tempo=100,beats=4;private View meter;private boolean visible;private final Handler handler=new Handler();private final Runnable tick=new Runnable(){public void run(){if(visible&&meter!=null){meter.invalidate();handler.postDelayed(this,120);}}};
 protected void onResume(){super.onResume();visible=true;handler.post(tick);}protected void onPause(){visible=false;handler.removeCallbacks(tick);super.onPause();}
 protected void render(){tempo=getSharedPreferences("pocket-metronome",0).getInt("bpm",100);beats=getSharedPreferences("pocket-metronome",0).getInt("beats",4);list(L.t("Metronom"),Arrays.asList(MetronomeService.instance==null?L.t("Pornește"):L.t("Oprește"),"BPM · "+tempo+" · ← / →",L.t("Bătăi pe măsură")+" · "+beats,L.t("Volum muzică")),0,new Choice(){public void pick(int at){if(at==0){if(MetronomeService.instance==null)start();else stopService(new Intent(MetronomeActivity.this,MetronomeService.class));handler.postDelayed(new Runnable(){public void run(){home();}},250);}else if(at==1)edit("BPM",new String[]{"30–240"},new String[]{""+tempo},new Saved(){public void save(String[] v)throws Exception{int n=Integer.parseInt(v[0]);if(n<30||n>240)throw new java.io.IOException("30–240 BPM");tempo=n;MetronomeActivity.this.save();}},goHome());else if(at==2){String[] counts={"1","2","3","4","5","6","7","8"};options(L.t("Bătăi pe măsură"),counts,new Choice(){public void pick(int n){beats=n+1;save();}});}else startActivity(new Intent(MetronomeActivity.this,QuickSettingsActivity.class).putExtra("volumes",true));}},"",null);meter=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){int beat=MetronomeService.instance==null?-1:MetronomeService.instance.beat();for(int n=0;n<beats;n++){p.setColor(n==beat?palette.accent:palette.card);c.drawCircle((n+1)*getWidth()/(beats+1f),getHeight()/2f,Math.min(10,getWidth()/(beats*3f)),p);}}};root.addView(meter,2,new LinearLayout.LayoutParams(-1,dp(40)));}
 private void save(){getSharedPreferences("pocket-metronome",0).edit().putInt("bpm",tempo).putInt("beats",beats).apply();if(MetronomeService.instance!=null)start();home();}
 private void start(){startForegroundService(new Intent(this,MetronomeService.class).putExtra("bpm",tempo).putExtra("beats",beats));}
 public boolean onKeyDown(int key,KeyEvent event){if(!form&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)){if(event.getRepeatCount()==0){tempo=Math.max(30,Math.min(240,tempo+(key==KeyEvent.KEYCODE_DPAD_RIGHT?5:-5)));save();}return true;}return super.onKeyDown(key,event);}
}
